answer:
function once<F extends (...args: any[]) => any>(fn: F): F {
  let called = false; let result: ReturnType<F>;
  return function(this: any, ...args: Parameters<F>) {
    if (!called) { called = true; result = fn.apply(this, args); }
    return result;
  } as F;
}
